// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public {
        c = new Owned();
    }

    function testFuzz_property(address ownerCandidate) public {
        vm.assume(ownerCandidate != address(0));

        vm.prank(c.owner());
        c.transferOwnership(ownerCandidate);

        address ownerBefore = c.owner();

        vm.prank(ownerCandidate);
        c.owned();

        address ownerAfter = c.owner();
        assertTrue(ownerAfter == ownerBefore, "owned() changed the owner");
    }
}
